import React, { useState } from 'react';
import axios from 'axios';

export default function ImageDetection() {
  const [image, setImage] = useState(null);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);

 const handleUpload = async () => {
  if (!image) return;

  const formData = new FormData();
  formData.append("file", image);
  setLoading(true);

  try {
    const res = await axios.post(
      `${process.env.REACT_APP_BACKEND_URL}/api/`, // change this path if needed
      formData
    );

    setResults(res.data); // res.data will contain all image paths
  } catch (err) {
    alert("Upload failed");
    console.error(err);
  } finally {
    setLoading(false);
  }
};

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <h2 className="text-2xl font-bold mb-4">🔍 Image Weapon Detection</h2>
      <input type="file" accept="image/*" onChange={e => setImage(e.target.files[0])} />
      <button onClick={handleUpload} className="mt-4 px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
        {loading ? "Processing..." : "Upload & Detect"}
      </button>

      {results && (
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mt-8">
          {Object.entries(results).map(([label, path]) => (
            <div key={label} className="text-center">
              <img src={`${process.env.REACT_APP_BACKEND_URL}/${path}`} alt={label} className="rounded shadow" />
              <p className="mt-2 font-semibold capitalize">{label.replace("_", " ")}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
